CREATE COLUMN TABLE "TEST_AP"."OPST" ("ProSubTyId" SMALLINT CS_INT NOT NULL , "Name" NVARCHAR(20) NOT NULL , "Descriptio" NCLOB MEMORY THRESHOLD 1000, "Active" NVARCHAR(1) DEFAULT 'Y', PRIMARY KEY ("ProSubTyId")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OPST_NAME" ON "TEST_AP"."OPST" ( "Name" ASC )